customCSS:
/* Garden dashboard - generated 2026-09-19. Desktop: 5 columns. Phone: 2 columns (auto flow). */
body,#app{background:#0c1411!important}
#grid-wrapper{grid-auto-rows:118px!important;grid-template-rows:none!important;padding:6px 8px 24px!important}
.tile{background:#15211c!important;border:1px solid #22332c;border-radius:16px!important;box-shadow:none!important;color:#e8f0ea!important;overflow:hidden}
.tile .tile-title{font:600 12px/1.2 -apple-system,"SF Pro Text","Segoe UI",sans-serif!important;letter-spacing:.02em;color:#9fb3a8!important;padding:10px 12px 0!important;text-align:left!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;visibility:hidden;position:relative}
.tile .tile-title:after{visibility:visible;position:absolute;left:12px;top:10px;right:12px;overflow:hidden;text-overflow:ellipsis}
.tile .tile-primary{font:600 26px/1.1 -apple-system,"SF Pro Display","Segoe UI",sans-serif!important;color:#f3f7f4!important}
.tile .tile-secondary{display:none!important}
.tile .tile-edit,.tile .tile-menu{display:none!important}
.tile .material-icons,.tile i{color:#9fb3a8}
.tile.switch:has(.tile-primary.on),.tile.outlet:has(.tile-primary.on){background:#3a2f12!important;border-color:#ffc857!important}
.tile .tile-primary.on i{color:#ffc857!important}
.tile.valve:has(.tile-primary.open){background:#10304a!important;border-color:#4ea8ff!important}
.tile.valve .tile-primary.open i{color:#4ea8ff!important}
.header{background:#0c1411!important;color:#9fb3a8!important}

#tile-1 .tile-title:after{content:"Fridge"}
#tile-1{border-left:3px solid #5fd0e0!important}
