#tile-1 .tile-primary{font-size:54px!important}

.tile .tile-contents{display:flex!important;flex-direction:column;align-items:center;justify-content:center;height:calc(100% - 30px)!important;padding:0 8px 8px!important}
.tile .tile-primary{display:flex;flex-direction:column;align-items:center;gap:2px}
.tile .tile-primary i,.tile .tile-primary .material-icons{font-size:30px!important;line-height:1!important}
#tile-5 .tile-primary i{display:none!important}
#tile-5:has(.tile-primary.on){background:#40200f!important;border-color:#ff8a5c!important}
